import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  bedrockKnowledgeStoreExactResponseFieldsSchema,
  type BedrockKnowledgeStoreExactResponseFields,
} from "./bedrock-knowledge-store-exact-response-fields.js";

export type BedrockKnowledgeStoreConfiguration = {
  /** The base ARN of the knowledge base used. */
  bedrockKnowledgeBaseArn: string;
  /**
   * Specifies whether to return an exact response, or to return an answer generated by the model,
   * using the fields you specify from the database.
   */
  exactResponse?: boolean;
  exactResponseFields?: BedrockKnowledgeStoreExactResponseFields;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const bedrockKnowledgeStoreConfigurationSchema: Schema<BedrockKnowledgeStoreConfiguration> =
  s.object<BedrockKnowledgeStoreConfiguration>(
    {
      bedrockKnowledgeBaseArn: s.string(),
      exactResponse: s.optional(s.boolean()),
      exactResponseFields: s.optional(s.lazy(() => bedrockKnowledgeStoreExactResponseFieldsSchema)),
    },
    { additionalProperties: s.json() },
  );
